"""scenes_kit v3.0.0: eight animated hero scenes (inline SVG + CSS keyframes, no JS) with their
captions and speaker notes in three locales. Each scene is a recipe for a kind of motion:
1 sequence reveal on a timeline, 2 typing in / result out, 3 converge into one, 4 pass or bounce,
5 loop ring with a traveling dot, 6 packets traveling on lanes, 7 toggles and a lock, 8 rising steps."""
import re
from visual_layer import ico
LOCS = ['en', 'pt-BR', 'es']
RED, YEL, BLU, GRN = 'var(--ps-color-ms-red-500)', 'var(--ps-color-ms-yellow-500)', 'var(--ps-color-ms-blue-500)', 'var(--ps-color-ms-green-500)'
INK3 = 'var(--ps-color-ink-3)'

def T(x, y, s, cls='m', anchor='start', extra=''):
    return f'<text class="{cls}" x="{x}" y="{y}" text-anchor="{anchor}" {extra}>{s}</text>'
def R(x, y, w, hh, fill='var(--ps-color-paper)', stroke='var(--ps-color-rule-2)', rx=8, extra=''):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{hh}" rx="{rx}" fill="{fill}" stroke="{stroke}" stroke-width="1.2" {extra}/>'
def G(cls, d, inner, extra=''):
    return f'<g class="{cls}" style="--d:{d}" {extra}>{inner}</g>'
def ICON(name, x, y, size=24, color=INK3):
    return f'<svg x="{x}" y="{y}" width="{size}" height="{size}" viewBox="0 0 24 24" style="color:{color}"><use href="#i-{name}"/></svg>'
def PILL(x, y, w, txt, col, d, cls='a-pop'):
    """The pill grows to fit its label and stays centred on the same point: a caption never leaves its frame."""
    cx = x + w / 2
    w = max(w, round(len(txt) * 7.35) + 28)
    x = cx - w / 2
    return G(cls, d, R(x, y, w, 26, f'color-mix(in srgb, {col} 16%, transparent)', col, 13) + T(cx, y + 17, txt, 'm m--b', 'middle', f'style="fill:{col}"'))

EVENTS = ['sessionStart', 'userPromptSubmitted', 'userPromptTransformed', 'permissionRequest', 'preToolUse', 'postToolUse', 'postToolUseFailure', 'agentStop', 'subagentStart', 'subagentStop', 'preCompact', 'errorOccurred', 'notification', 'sessionEnd']
BLOCK = {'permissionRequest', 'preToolUse', 'agentStop'}

# ------------------------------------------------------------------ scene I
def scene1():
    p = []
    p.append(G('a-draw', 100, f'<path class="ln" d="M70 190 H1050" pathLength="100" style="stroke-width:2"/>'))
    p.append(G('a-in', 0, ICON('laptop', 18, 176, 30, 'var(--ps-color-ink)')))
    p.append(G('a-pop', 2600, ICON('flag', 1068, 176, 30, RED)))
    x0, step = 96, 73
    for i, ev in enumerate(EVENTS):
        x = x0 + i * step; d = 400 + i * 150; blk = ev in BLOCK
        col = RED if blk else BLU
        ring = f'<circle class="a-pulse" cx="{x}" cy="190" r="14" fill="none" stroke="{RED}" stroke-width="2" style="--d:{d+300}"/>' if blk else ''
        p.append(G('a-pop', d, f'<circle cx="{x}" cy="190" r="{9 if blk else 7}" fill="{col}"/>' + ring))
        # labels alternate above and below; the two loop events (4, 5) flank the loop arc so nothing crosses a label
        up = (i % 2 == 0) if i < 4 else (i in (4, 5) or i % 2 == 1)
        ly = 150 if up else 236
        anchor, lx = 'middle', x
        if i == 4: anchor, lx, ly = 'end', x - 12, 132
        if i == 5: anchor, lx, ly = 'start', x + 12, 132
        tick = f'<path class="ln" d="M{x} {190 - 11 if up else 190 + 11} V{ly + 8 if up else ly - 14}" style="stroke-width:1;opacity:.6"/>' if i not in (4, 5) else ''
        p.append(G('a-in', d + 80, tick + T(lx, ly, ev, 'm', anchor, f'style="fill:{RED if blk else "var(--ps-color-ink-2)"};font-weight:{700 if blk else 500}"')))
    # tool loop arc over preToolUse(4) .. postToolUse(5)
    xa, xb = x0 + 4 * step, x0 + 5 * step
    loop = f'M{xa} 178 C{xa} 112 {xb} 112 {xb} 178'
    p.append(G('a-in', 2900, f'<path d="{loop}" fill="none" stroke="{YEL}" stroke-width="2" stroke-dasharray="4 4"/>' + T((xa + xb) / 2, 118, 'loop', 'm', 'middle', f'style="fill:var(--ps-text-yellow)"')))
    p.append(f'<circle r="4" fill="{YEL}" opacity="0"><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.1;.9;1" dur="2.4s" begin="3.2s" repeatCount="indefinite"/><animateMotion dur="2.4s" begin="3.2s" repeatCount="indefinite" path="{loop}"/></circle>')
    # turn bracket
    xt0, xt1 = x0 + 1 * step, x0 + 7 * step
    p.append(G('a-in', 2700, f'<path class="ln" d="M{xt0} 262 V276 H{xt1} V262" style="stroke:{YEL};stroke-width:2"/>' + T((xt0 + xt1) / 2, 300, '', 'm m--b', 'middle', f'style="fill:var(--ps-text-yellow)" data-i18n="sc1.turn"')))
    xs0, xs1 = x0 + 8 * step, x0 + 12 * step
    p.append(G('a-in', 2800, f'<path class="ln" d="M{xs0} 262 V276 H{xs1} V262" style="stroke:{GRN};stroke-width:2"/>' + T((xs0 + xs1) / 2, 300, '', 'm m--b', 'middle', f'style="fill:var(--ps-text-green)" data-i18n="sc1.any"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene II
def scene2():
    p = []
    p.append(G('a-in', 0, R(40, 30, 330, 250) + T(58, 56, 'stdin · JSON', 'm m--b') + ICON('json', 330, 40, 22, GRN)))
    lines = [('"event"', 120, BLU), ('"sessionId"', 150, INK3), ('"toolName": "bash"', 170, BLU), ('"toolArgs"', 130, INK3), ('  "command": "git push --force"', 240, RED), ('"cwd"', 90, INK3), ('"timestamp"', 120, INK3)]
    for i, (lab, w, col) in enumerate(lines):
        y = 78 + i * 27
        p.append(G('a-type', 300 + i * 160, f'<rect x="58" y="{y}" width="{w}" height="14" rx="3" fill="{col}" opacity=".18"/>' + T(64, y + 11, lab, 'm', 'start', f'style="fill:{col};font-size:10.5px"')))
    p.append(G('a-draw', 1150, f'<path class="ln" d="M370 155 H470" pathLength="100" marker-end="url(#sc-ar-g)" style="stroke:{GRN};stroke-width:2"/>'))
    p.append(G('a-flash', 1350, R(470, 100, 180, 110, 'var(--ps-color-paper)', GRN, 12, 'stroke-width="2"') + ICON('terminal', 545, 112, 30, GRN) + T(560, 166, 'hook', 'lbl', 'middle') + T(560, 186, 'command · 180 ms', 'm', 'middle')))
    p.append(f'<rect class="a-pulse" x="470" y="100" width="180" height="110" rx="12" fill="none" stroke="{GRN}" stroke-width="2" style="--d:1650;opacity:.5"/>')
    p.append(G('a-draw', 1850, f'<path class="ln" d="M650 155 H750" pathLength="100" marker-end="url(#sc-ar-g)" style="stroke:{GRN};stroke-width:2"/>'))
    p.append(G('a-in', 0, R(750, 30, 330, 250) + T(768, 56, 'stdout · JSON', 'm m--b') + ICON('json', 1040, 40, 22, GRN)))
    out = [('{', INK3), ('  "permissionDecision": "deny",', RED), ('  "permissionDecisionReason":', INK3), ('    "No force push to main.', 'var(--ps-color-ink)'), ('     Open a pull request."', 'var(--ps-color-ink)'), ('}', INK3)]
    for i, (lab, col) in enumerate(out):
        p.append(G('a-in', 2050 + i * 130, T(768, 86 + i * 24, lab, 'm', 'start', f'style="fill:{col}"')))
    p.append(PILL(500, 236, 120, 'exit 0', GRN, 2900))
    p.append(PILL(500, 274, 120, 'stdout → decision', BLU, 3080))
    return ''.join(p)

# ------------------------------------------------------------------ scene III
def scene3():
    p = []
    src = [('policy.d/*.json', RED, 'admin'), ('.github/hooks/*.json', BLU, 'repo'), ('~/.copilot/hooks/*.json', BLU, 'user'), ('.github/copilot/settings.json', BLU, 'repo'), ('~/.copilot/settings.json', BLU, 'user'), ('plugin hooks.json', GRN, 'plugin')]
    for i, (lab, col, who) in enumerate(src):
        y = 18 + i * 46
        p.append(G('a-slide', 200 + i * 220, R(60, y, 330, 38) + f'<rect x="60" y="{y}" width="5" height="38" rx="2" fill="{col}"/>' + T(80, y + 24, f'{i+1}', 'm m--b', 'start', f'style="fill:{col}"') + T(100, y + 24, lab, 'm', 'start', 'style="fill:var(--ps-color-ink)"') + T(380, y + 24, who, 'm', 'end', f'style="fill:{col}"')))
        p.append(G('a-draw', 600 + i * 220, f'<path class="ln" d="M390 {y+19} C520 {y+19} 560 165 690 165" pathLength="100" style="stroke:{col};opacity:.7"/>'))
    p.append(G('a-pop', 2100, f'<circle cx="690" cy="165" r="10" fill="{YEL}"/>'))
    p.append(G('a-draw', 2200, f'<path class="ln" d="M700 165 H780" pathLength="100" marker-end="url(#sc-ar-y)" style="stroke:{YEL};stroke-width:2"/>'))
    p.append(G('a-pop', 2500, R(780, 105, 300, 120, 'var(--ps-color-paper)', YEL, 12, 'stroke-width="2"') + T(930, 150, '1', 'lbl', 'middle', 'style="font-size:44px;font-family:var(--ps-font-mono);font-weight:700;fill:var(--ps-text-yellow)"') + T(930, 178, '', 'm m--b', 'middle', 'data-i18n="sc3.one"') + T(930, 200, 'entries run in order', 'm', 'middle', 'data-i18n="sc3.order"')))
    p.append(G('a-in', 3000, T(560, 322, '', 'm', 'middle', 'data-i18n="sc3.note" style="fill:var(--ps-color-ink-3)"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene IV
def scene4():
    p = []
    # shield
    p.append(G('a-pop', 200, f'<circle cx="560" cy="165" r="62" fill="color-mix(in srgb, {BLU} 10%, transparent)"/>' + ICON('shield', 524, 129, 72, BLU) + T(560, 252, 'preToolUse', 'm m--b', 'middle', f'style="fill:var(--ps-text-blue)"')))
    # command 1 passes
    sg = 'style="fill:var(--ps-text-green)"'
    p.append('<g class="a-pass" style="--d:900">' + R(0, 96, 150, 30, f'color-mix(in srgb, {GRN} 16%, transparent)', GRN, 15) + T(75, 116, 'npm test', 'm m--b', 'middle', sg) + '</g>')
    p.append(G('a-pop', 3000, ICON('check', 1010, 96, 30, GRN) + T(1025, 150, 'allow', 'm m--b', 'middle', f'style="fill:var(--ps-text-green)"')))
    # command 2 bounces
    sr = 'style="fill:var(--ps-text-red);font-size:10.5px"'
    p.append('<g class="a-bounce" style="--d:3400">' + R(0, 204, 190, 30, f'color-mix(in srgb, {RED} 16%, transparent)', RED, 15) + T(95, 224, 'rm -rf / --no-preserve-root', 'm m--b', 'middle', sr) + '</g>')
    p.append(f'<circle class="a-hit" cx="560" cy="165" r="62" fill="none" stroke="{RED}" stroke-width="3" style="--d:4300"/>')
    p.append(G('a-in', 4700, R(700, 190, 380, 74, 'var(--ps-color-paper)', RED, 10) + f'<rect x="700" y="190" width="5" height="74" rx="2" fill="{RED}"/>' + T(720, 214, 'deny', 'm m--b', 'start', f'style="fill:var(--ps-text-red)"') + T(720, 234, '"Destructive delete. Use a scoped path."', 'm', 'start') + T(720, 252, 'exit 0 · reason goes back to the agent', 'm', 'start', f'style="fill:{INK3};font-size:10px"')))
    p.append(G('a-in', 5200, T(560, 312, '', 'm', 'middle', 'data-i18n="sc4.note" style="fill:var(--ps-color-ink-3)"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene V
def scene5():
    p = []
    cx, cy, r = 560, 176, 98
    p.append(G('a-draw', 200, f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{RED}" stroke-width="2" stroke-dasharray="6 5" pathLength="100" class="ln"/>'))
    # the traveling dot is drawn before the stations, so it passes under them and never over an icon
    p.append(f'<circle r="6" fill="{RED}" opacity="0"><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.05;.95;1" dur="4s" begin="0.6s" repeatCount="indefinite"/><animateMotion dur="4s" begin="0.6s" repeatCount="indefinite" path="M{cx} {cy-r} A{r} {r} 0 1 1 {cx-0.01} {cy-r}"/></circle>')
    nodes = [(cx, cy - r, 'agentStop', RED, 700), (cx + r, cy, 'tests?', YEL, 1500), (cx, cy + r, 'block + reason', RED, 2300), (cx - r, cy, 'npm test', GRN, 3100)]
    for x, y, a, col, d in nodes:
        p.append(G('a-pop', d, f'<circle cx="{x}" cy="{y}" r="30" fill="var(--ps-color-paper)" stroke="{col}" stroke-width="2.5"/>' + ICON({'agentStop': 'flag', 'tests?': 'test', 'block + reason': 'ban', 'npm test': 'check'}[a], x - 12, y - 12, 24, col)))
    # labels sit outside the ring with at least 12px of air from every node edge
    p.append(G('a-in', 800, T(cx, cy - r - 52, 'agentStop', 'lbl', 'middle') + T(cx, cy - r - 36, 'wants to stop', 'm', 'middle')))
    p.append(G('a-in', 1600, T(cx + r + 46, cy - 4, 'stop_hook_active = false', 'm', 'start') + T(cx + r + 46, cy + 14, 'tests not run yet', 'm m--b', 'start', f'style="fill:var(--ps-text-yellow)"')))
    p.append(G('a-in', 2400, T(cx, cy + r + 50, '{"decision":"block","reason":"Run npm test"}', 'm', 'middle', f'style="fill:var(--ps-text-red)"')))
    p.append(G('a-in', 3200, T(cx - r - 46, cy - 4, 'forced turn', 'm m--b', 'end', f'style="fill:var(--ps-text-green)"') + T(cx - r - 46, cy + 14, 'agent runs the tests', 'm', 'end')))
    p.append(G('a-pop', 4200, f'<circle cx="{cx}" cy="{cy}" r="36" fill="color-mix(in srgb, {GRN} 14%, transparent)"/>' + ICON('check', cx - 16, cy - 16, 32, GRN) + T(cx, cy + 50, 'stop ✓ · block 1/8', 'm m--b', 'middle', f'style="fill:var(--ps-text-green)"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene VI
def scene6():
    p = []
    p.append(G('a-in', 0, R(40, 100, 220, 130) + ICON('laptop', 130, 118, 40, 'var(--ps-color-ink)') + T(150, 190, 'GitHub Copilot CLI', 'lbl', 'middle') + T(150, 210, 'hooks run here', 'm', 'middle')))
    lanes = [(60, 'SIEM · Log Analytics', 'cloud', GRN, 'http hook', 'hook.end · deny · session id'), (165, 'OpenTelemetry', 'chart', BLU, 'span events', 'hook.start · hook.end · traceparent'), (270, 'GitHub audit log', 'shield', YEL, 'platform', 'agent_session.* · no local prompts')]
    for i, (y, lab, icn, col, tag, sub) in enumerate(lanes):
        d = 400 + i * 350
        dash = ' stroke-dasharray="5 5"' if i == 2 else ''
        p.append(G('a-draw', d, f'<path class="ln" d="M260 165 C420 165 420 {y} 560 {y} H820" pathLength="100" style="stroke:{col};stroke-width:2"{dash}/>'))
        p.append(G('a-in', d + 300, T(690, y - 24, tag, 'm m--b', 'middle', f'style="fill:{col}"')))
        p.append(G('a-pop', d + 500, R(820, y - 36, 300, 72) + f'<rect x="820" y="{y-36}" width="5" height="72" rx="2" fill="{col}"/>' + ICON(icn, 838, y - 14, 28, col) + T(878, y - 6, lab, 'lbl') + T(878, y + 14, sub, 'm', 'start', 'style="font-size:10px"')))
        if i < 2:
            for k in range(3):
                p.append(f'<rect width="18" height="10" rx="2" fill="{col}" opacity="0"><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.08;.92;1" dur="3s" begin="{2 + k + i * 0.4}s" repeatCount="indefinite"/><animateMotion dur="3s" begin="{2 + k + i * 0.4}s" repeatCount="indefinite" path="M251 160 C411 160 411 {y-5} 551 {y-5} H811"/></rect>')
    p.append(G('a-in', 1900, R(560, 292, 250, 26, f'color-mix(in srgb, {RED} 14%, transparent)', RED, 13) + T(685, 309, 'not captured: local prompts, args', 'm m--b', 'middle', f'style="fill:var(--ps-text-red);font-size:10.5px"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene VII
def scene7():
    p = []
    rows = [('~/.copilot/hooks', 'user', True), ('.github/hooks', 'repo', True), ('settings.json', 'inline', True), ('policy.d · managed', 'admin', False)]
    for i, (lab, who, off) in enumerate(rows):
        y = 30 + i * 66; d = 300 + i * 600
        col = RED if not off else BLU
        p.append(G('a-in', 100 + i * 120, R(60, y, 560, 50) + f'<rect x="60" y="{y}" width="5" height="50" rx="2" fill="{col}"/>' + T(84, y + 31, lab, 'lbl') + T(300, y + 31, who, 'm', 'start', f'style="fill:{INK3}"')))
        if off:
            p.append(G('a-in', 100 + i * 120, f'<rect x="440" y="{y+14}" width="52" height="24" rx="12" fill="{GRN}" opacity=".85"/>' + f'<circle class="a-flip" cx="479" cy="{y+26}" r="9" fill="#fff" style="--d:{d}"/>'))
            p.append(G('a-in', d + 400, T(506, y + 31, 'off', 'm m--b', 'start', f'style="fill:{INK3}"')))
            p.append(f'<rect class="a-in" x="440" y="{y+14}" width="52" height="24" rx="12" fill="{INK3}" opacity=".35" style="--d:{d+200}"/>')
        else:
            p.append(G('a-in', 100 + i * 120, f'<rect x="440" y="{y+14}" width="52" height="24" rx="12" fill="{RED}"/><circle cx="479" cy="{y+26}" r="9" fill="#fff"/>'))
            p.append(G('a-in', 2900, T(506, y + 31, 'on', 'm m--b', 'start', f'style="fill:var(--ps-text-red)"')))
            p.append(G('a-shake', 2500, ICON('lock', 560, y + 12, 26, RED)))
    p.append(G('a-in', 2000, R(660, 60, 420, 200, 'var(--ps-color-paper)', RED, 12, 'stroke-width="2"') + ICON('lock', 680, 78, 26, RED) + T(716, 97, 'managed settings', 'lbl') + T(680, 130, '"allowManagedHooksOnly": true', 'm', 'start', f'style="fill:var(--ps-text-red)"') + T(680, 152, '"disableBypassPermissionsMode": "disable"', 'm') + T(680, 174, '"permissions": { "deny": ["Shell(rm -rf *)"] }', 'm') + T(680, 210, '', 'm m--b', 'start', 'data-i18n="sc7.who"') + T(680, 232, '', 'm', 'start', 'data-i18n="sc7.how" style="fill:var(--ps-color-ink-3)"')))
    p.append(G('a-in', 3400, T(560, 312, '', 'm', 'middle', 'data-i18n="sc7.note" style="fill:var(--ps-color-ink-3)"')))
    return ''.join(p)

# ------------------------------------------------------------------ scene VIII
def scene8():
    p = []
    steps = [('observe', 'week 1', 'eye', BLU), ('protect', 'weeks 2 to 4', 'shield', GRN), ('automate', 'month 2', 'wrench', YEL), ('govern', 'month 3', 'lock', RED)]
    base = 300; W = 236; X0 = 70; GAP = 250
    for i, (lab, when, icn, col) in enumerate(steps):
        x = X0 + i * GAP; hh = 60 + i * 54; y = base - hh; d = 300 + i * 500
        p.append(G('a-rise', d, R(x, y, W, hh, f'color-mix(in srgb, {col} 12%, transparent)', col, 10, 'stroke-width="1.5"') + f'<rect x="{x}" y="{y}" width="{W}" height="6" rx="3" fill="{col}"/>' + ICON(icn, x + 16, y + 20, 28, col) + T(x + 56, y + 32, '', 'lbl', 'start', f'data-i18n="sc8.s{i+1}"') + T(x + 56, y + 52, '', 'm', 'start', f'data-i18n="sc8.w{i+1}" style="fill:{INK3};font-size:10px"') + T(x + W - 12, y + hh - 12, f'{i+1}', 'm', 'end', f'style="fill:{col};font-size:30px;font-weight:700;opacity:.35"')))
    p.append(G('a-draw', 400, f'<path class="ln" d="M40 {base+6} H1080" pathLength="100" style="stroke-width:2"/>'))
    # climbing dot: rises to 16px above each step, runs along the top, ends over the middle of the last step
    pts = [f'M40 {base-16}']
    for i in range(4):
        x = X0 + i * GAP; y = base - (60 + i * 54) - 16
        pts.append(f'L{x + 12} {y} L{x + (W // 2 if i == 3 else W - 12)} {y}')
    p.append(f'<circle r="8" fill="{RED}" opacity="0"><animate attributeName="opacity" values="0;1;1;1" keyTimes="0;.1;.9;1" dur="4.4s" begin="0.8s" fill="freeze"/><animateMotion dur="4.4s" begin="0.8s" fill="freeze" path="{" ".join(pts)}"/></circle>')
    x4 = X0 + 3 * GAP; y4 = base - (60 + 3 * 54)
    # the goal sits above the last step, right-aligned to its edge, so a longer language never leaves the canvas
    p.append(G('a-pop', 5400, ICON('flag', x4 + W - 34, y4 - 56, 26, RED) + T(x4 + W - 44, y4 - 36, '', 'm m--b', 'end', 'data-i18n="sc8.goal" style="fill:var(--ps-text-red)"')))
    return ''.join(p)

