SCENE_KINDS = {
    1: 'lifecycle',
    2: 'input-output',
    3: 'convergence',
    4: 'gate',
    5: 'loop',
    6: 'lanes',
    7: 'flip-lock',
    8: 'maturity',
}


def scene_svg(n):
    kind = SCENE_KINDS[n]
    return f'<svg class="scn" data-scene-kind="{kind}" viewBox="0 0 1120 330" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{kind.replace("-", " ")} animated scene">{MARKER}{SCENES[n]["fn"]()}</svg>'

def scene_caps(n, key, reg):
    """reg(key, en, pt, es) registers an i18n string and returns the data-i18n attribute."""
    sc = SCENES[n]; out = []
    for i, (col, caps) in enumerate(sc['caps'], 1):
        out.append(f'<div class="cap" style="--c:var(--ps-color-ms-{col}-500);--i:{i-1}"><b {reg(f"{key}.c{i}t", caps["en"][0], caps["pt-BR"][0], caps["es"][0])}>{caps["en"][0]}</b><span {reg(f"{key}.c{i}d", caps["en"][1], caps["pt-BR"][1], caps["es"][1])}>{caps["en"][1]}</span></div>')
    return '<div class="scene__caps">' + ''.join(out) + '</div>'
